    const size = 9*9;
    for(let i=0;i<size;i++){
      const cell = document.createElement('i');
      const r = rand(i);
      const row = Math.floor(i/9), col = i%9;
      const finder = (row<3 && col<3) || (row<3 && col>5) || (row>5 && col<3);
      const timing = (row===4 || col===4);
      const on = finder ? ((row===1||col===1||row===0||col===0||row===2||col===2) ? true : false) : (timing ? (i%2===0) : (r>0.58));
      if(on) cell.classList.add('on');
